            $objBinaryWriter.Write([uint16]20)
            $objBinaryWriter.Write([uint16]20)
            $objBinaryWriter.Write([uint16]0)
            $objBinaryWriter.Write([uint16]0)
            $objBinaryWriter.Write([uint16]0)
